import { writeFile } from 'node:fs/promises';
export default async function (config) {
  const response = await fetch(`${config.projects[0].use.baseURL}/api/plans/generate`, {
    method: 'POST', headers: {'content-type':'application/json'},
    body: JSON.stringify({query:'3 pubs in Piccadilly & Soho, under £18 per person, maximum £6 per pint'}),
  });
  await writeFile(process.env.PROBE_PATH!, JSON.stringify({status:response.status, body:await response.json()}, null, 2));
}

